t[7639] = {"To Show Due Judgment", 1, 5, 2, 60, 60, 1, 1455, 2, nil, {1, 11406, 1455, 24.7, 8.2}, {1, 928, 1453, 48.4, 50.2}, nil, "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", {provided = {18819}}, {rep = {{"Stormwind", 50}}}, 75, 1, {all = {7637}}, nil, nil, {7638, 3, 11}}
t[7640] = {"Exorcising Terrordale", 1, 5, 2, 60, 60, 1, 1453, 2, nil, {1, 928, 1453, 48.4, 50.2}, {1, 928, 1453, 48.4, 50.2}, {{1423, 8.1, 20.9}}, "Use the Exorcism Censer to drive out the spirits that torment Terrordale. When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", {provided = {18752}}, {money = 19800, rep = {{"Stormwind", 100}}}, 725, 1, {all = {7639}}, nil, nil, {7638, 4, 11}}
