t[7642] = {"Collection of Goods", 1, 5, 2, 60, 60, 1, 1453, 34, 5, {1, 1416, 1453, 59.7, 33.8}, {1, 1416, 1453, 59.7, 33.8}, {{1422, 30.3, 60.5}, {1423, 21.6, 76.5}, {1448, 37.3, 61.4}}, "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind.", {required = {{13180, 1}, {8836, 1}, {14047, 1}, {12360, 1}}}, {rep = {{"Ironforge", 100}}}, 180, 1, {all = {7641}}, nil, nil, {7638, 6, 11}}
t[7643] = {"Ancient Equine Spirit", 1, 5, 2, 60, 60, 1, 1453, 34, 5, {1, 928, 1453, 48.4, 50.2}, {1, 14566}, nil, "Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food.\nTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it.", {provided = {18753}, required = {{18775, 1}}}, {money = 14850}, 1100, 1, {all = {7642}}, nil, nil, {7638, 7, 11}}
t[7646] = {"The Divination Scryer", 1, 5, 2, 60, 60, 1, 1453, 2, nil, {1, 928, 1453, 48.4, 50.2}, {1, 928, 1453, 48.4, 50.2}, {{1423, 17.0, 56.5}, {1423, 73.9, 74.1}, {1428, 12.1, 32.1}, {1419, 38.0, 34.7}, {1419, 42.6, 13.0}, {1452, 55.5, 43.6}, {1452, 52.3, 84.7}, {1425, 20.8, 58.8}, {1451, 17.9, 66.5}, {1449, 24.3, 56.6}, {1422, 43.5, 33.4}, {1422, 40.4, 71.9}, {1427, 15.7, 32.4}, {1447, 46.3, 83.4}, {1446, 26.8, 65.6}, {1448, 34.7, 61.8}, {1444, 45.4, 69.4}, {1424, 14.1, 83.9}}, "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", {required = {{12800, 1}, {18335, 1}}}, {rep = {{"Stormwind", 50}}}, 370, 1, {all = {7644}}, nil, nil, {7638, 9, 11}}
t[7647] = {"Judgment and Redemption", 1, 5, 2, 60, 60, 1, 1453, 34, 5, {1, 928, 1453, 48.4, 50.2}, {1, 14568}, nil, "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger.\nGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger.", {provided = {18804}, required = {{18799, 1}, {18792, 1}}}, {money = 29850, rep = {{"Stormwind", 200}}}, 2200, 1, {all = {7646}}, nil, nil, {7638, 10, 11}}
