t[7701] = {"WANTED: Overseer Maltorius", 3, nil, nil, 45, 50, 1, 1427, 1, nil, {2, 179827, 1427, 37.7, 26.5}, {1, 14634, 1427, 37.7, 26.6}, {{1427, 40.8, 35.9}}, "Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.\nSlay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.", {required = {{18946, 1}}}, {choice = {{19128, 1}, {19127, 1}, {270113, 1}}, rep = {{"Thorium Brotherhood", 100}}}, 4700, 1}
t[7721] = {"Fuel for the Zapping", 3, nil, nil, 45, 48, 1, 1444, 0, nil, {1, 14637, 1444, 44.8, 43.4}, {1, 14637, 1444, 44.8, 43.4}, {{1444, 34.4, 35.6}}, "Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.", {required = {{18958, 1}}}, {fixed = {{19039, 1}}, money = 7000, rep = {{"Steamwheedle Cartel", 150}}}, 4400, 1, nil, nil, nil, {7721, 1, 2}}
t[7722] = {"What the Flux?", 3, nil, nil, 45, 50, 1, 1427, 0, nil, {1, 14624, 1427, 38.8, 28.5}, {1, 14624, 1427, 38.8, 28.5}, {{1427, 40.5, 35.7}}, "Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge.", {required = {{18922, 1}}}, {money = 10413, rep = {{"Thorium Brotherhood", 100}}}, 4700, 1, nil, nil, nil, {7722, 1, 2}}
t[7723] = {"Curse These Fat Fingers", 3, nil, nil, 45, 49, 1, 1427, 0, nil, {1, 14627, 1427, 38.6, 27.8}, {1, 14627, 1427, 38.6, 27.8}, {{1427, 32.5, 52.6}}, "Hansel Heavyhands wants you to kill 20 Heavy War Golems.\nThe Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge.", nil, {fixed = {{19126, 1}}, money = 7000, rep = {{"Thorium Brotherhood", 100}}}, 4550, 1}
